// Writes src/database.generated.ts from database/phreeqc.dat and
// database/pool.dat so the Worker and the phone get the database as a plain
// string. Run after changing either file: pnpm --filter @poolos/pool-chemistry embed
// test/database.spec.ts fails if the generated file is out of date.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

const dir = new URL('../', import.meta.url);
const read = (name) => readFileSync(new URL(`database/${name}`, dir));
const sha = (buf) => createHash('sha256').update(buf).digest('hex');

const phreeqc = read('phreeqc.dat');
const pool = read('pool.dat');
// phreeqc.dat is Latin-1 (degree signs in comments); keep every byte.
const out = `// Generated by scripts/embed-database.mjs. Do not edit.
export const PHREEQC_DAT_SHA256 = ${JSON.stringify(sha(phreeqc))};
export const POOL_DAT_SHA256 = ${JSON.stringify(sha(pool))};
export const PHREEQC_DAT = ${JSON.stringify(phreeqc.toString('latin1'))};
export const POOL_DAT = ${JSON.stringify(pool.toString('utf8'))};
`;
writeFileSync(new URL('src/database.generated.ts', dir), out);
console.log('wrote src/database.generated.ts');
